/**
 * The `pdpp-safe-escape-v1` text encoding: a lossless, deterministic way to
 * carry source text that PDPP text cannot hold as is (control characters, lone
 * surrogates). Copied from connectors/chatgpt/parsers.ts
 * (tnunamak/pdpp-chatgpt-port-1015 @ed8bc4219) and kept byte-identical in
 * behavior; safe-escape-vectors.json holds vectors generated by that code and
 * safe-escape.test.ts checks this module against them.
 *
 * TODO(pdpp-shared-text-codec): hoist into polyfill-connectors once both ports merge
 *
 * The escaped set is FIXED so a reader can mirror it without the validator:
 * U+0000-0008, U+000B, U+000C, U+000E-001F, U+007F-009F (the C0/C1 controls
 * PDPP text forbids; tab, LF and CR are allowed) and lone surrogates (not
 * UTF-8 encodable). Noncharacters (U+FDD0.., U+xFFFE/xFFFF on every plane) and
 * valid surrogate pairs are ordinary scalar values and pass through. The `u`
 * flag keeps valid surrogate pairs whole so only lone ones match. The first
 * alternative finds a source backslash that starts something the decoder would
 * read as an escape.
 */

/** Longest text kept inline in a record field, measured on the escaped form. */
export const INLINE_TEXT_MAX_UNITS = 10_000_000;

const ESCAPE_SCAN =
	// biome-ignore lint/suspicious/noControlCharactersInRegex: the escaped set IS these control characters
	/\\u([0-9a-fA-F]{4})|[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f-\u009f\ud800-\udfff]/gu;
const ESCAPE_TOKEN = /\\u([0-9a-fA-F]{4})/g;
const BACKSLASH_UNIT = 0x5c;

/** Code units the encoding writes as `\uXXXX`: forbidden controls, lone surrogates and backslash. */
export function isEscapedUnit(unit: number): boolean {
	return (
		unit === BACKSLASH_UNIT ||
		unit <= 0x08 ||
		unit === 0x0b ||
		unit === 0x0c ||
		(unit >= 0x0e && unit <= 0x1f) ||
		(unit >= 0x7f && unit <= 0x9f) ||
		(unit >= 0xd8_00 && unit <= 0xdf_ff)
	);
}

function escapeSequence(unit: number): string {
	return `\\u${unit.toString(16).toUpperCase().padStart(4, "0")}`;
}

/** Each position of `s` that the encoding rewrites, and the code unit it writes. */
function* escapeSites(s: string): Generator<{ index: number; unit: number }> {
	for (const match of s.matchAll(ESCAPE_SCAN)) {
		const hex = match[1];
		const index = match.index ?? 0;
		if (hex === undefined) {
			yield { index, unit: match[0].charCodeAt(0) };
		} else if (isEscapedUnit(Number.parseInt(hex, 16))) {
			yield { index, unit: BACKSLASH_UNIT };
		}
	}
}

/**
 * Lossless, deterministic PDPP-safe encoding of text. Each escaped unit becomes
 * `\uXXXX` (uppercase hex). A source backslash that begins a `\uXXXX` the
 * decoder would read as an escape is itself written `\u005C`, so decoding is
 * unambiguous. All other text, including ordinary backslashes, is unchanged.
 */
export function encodePdppSafeText(s: string): string {
	const parts: string[] = [];
	let last = 0;
	for (const { index, unit } of escapeSites(s)) {
		parts.push(s.slice(last, index), escapeSequence(unit));
		last = index + 1;
	}
	if (parts.length === 0) return s;
	parts.push(s.slice(last));
	return parts.join("");
}

/** Inverse of the encoding: restores the exact source text. */
export function decodeEscapedText(s: string): string {
	return s.replace(ESCAPE_TOKEN, (match, hex: string) => {
		const unit = Number.parseInt(hex, 16);
		return isEscapedUnit(unit) ? String.fromCharCode(unit) : match;
	});
}

/**
 * Whether the escaped form of `raw` is longer than `cap`, decided without
 * building it. Each escape adds five characters, so the length is
 * `raw.length + 5 * sites`; the scan stops once that passes `cap`, and a `raw`
 * already longer than `cap` is not scanned at all.
 */
export function escapedLengthExceeds(
	raw: string,
	cap: number = INLINE_TEXT_MAX_UNITS,
): { exceeds: boolean; sitesVisited: number } {
	if (raw.length > cap) return { exceeds: true, sitesVisited: 0 };
	let length = raw.length;
	let sitesVisited = 0;
	for (const _site of escapeSites(raw)) {
		sitesVisited += 1;
		length += 5;
		if (length > cap) return { exceeds: true, sitesVisited };
	}
	return { exceeds: false, sitesVisited };
}
